{
  "findings": [
    {
      "check_id": "CKV_GCP_25",
      "title": "Ensure Kubernetes Cluster is created with Private cluster enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster is not configured as a private cluster, which increases the risk of unauthorized access to the control plane and nodes."
    },
    {
      "check_id": "AVD-GCP-0056",
      "title": "Cluster does not have a network policy enabled.",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster does not have a network policy enabled, which allows unrestricted inter-cluster communication and increases the risk of lateral movement in case of a compromise."
    },
    {
      "check_id": "CKV_GCP_23",
      "title": "Ensure Kubernetes Cluster is created with Alias IP ranges enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Alias IP ranges are not enabled, which is required for better IP address management and to avoid IP conflicts in the cluster."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Legacy ABAC is enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Legacy ABAC (Attribute-Based Access Control) is enabled, which is deprecated and poses a security risk by allowing overly permissive access."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Kubernetes alpha features are enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Enabling Kubernetes alpha features can introduce instability and potential security vulnerabilities as these features are not production-ready."
    }
  ],
  "patched_code": "resource "google_container_cluster" "k8sexample" {
  name               = "${var.vault_user}-k8s-cluster"
  description        = "example k8s cluster"
  zone               = "${var.gcp_zone}"
  initial_node_count = "${var.initial_node_count}"

  # Disable Kubernetes alpha features
  enable_kubernetes_alpha = false

  # Disable legacy ABAC
  enable_legacy_abac = false

  # Enable private cluster
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = true
  }

  # Enable network policy
  network_policy {
    enabled = true
    provider = "CALICO"
  }

  # Enable Alias IP ranges
  ip_allocation_policy {
    use_ip_aliases = true
  }

  master_auth {
    username = "${var.master_username}"
    password = "${var.master_password}"
    client_certificate_config {
      issue_client_certificate = true
    }
  }

  node_config {
    machine_type = "${var.node_machine_type}"
    disk_size_gb = "${var.node_disk_size}"
    oauth_scopes = [
      "https://www.googleapis.com/auth/compute",
      "https://www.googleapis.com/auth/devstorage.read_only",
      "https://www.googleapis.com/auth/logging.write",
      "https://www.googleapis.com/auth/monitoring"
    ]
  }
}",
  "fix_summary": "Disabled Kubernetes alpha features and legacy ABAC for improved security. Enabled private cluster configuration, network policy, and Alias IP ranges to enhance cluster security and IP management."
}
